SELECT COUNT(*) AS pairs, SUM(f.generated_at > o.generated_at) AS five_after_1m, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, o.generated_at, f.generated_at))/1000) AS avg_delta_ms, MIN(o.generated_at) AS first_ksa, MAX(o.generated_at) AS last_ksa FROM crypto_ai.trade_signal o JOIN crypto_ai.trade_signal f ON f.symbol=o.symbol AND f.interval_code='5m' AND f.candle_open_time = o.candle_open_time - INTERVAL 4 MINUTE WHERE o.interval_code='1m' AND MINUTE(o.candle_open_time) % 5 = 4 AND o.generated_at BETWEEN '2026-10-11 00:00:00' AND '2026-10-17 04:00:00';
SELECT w.id AS wallet_trade_id, w.signal_id, w.execution_reason, o.symbol, o.candle_open_time, f.id AS five_same_close, f.decision AS five_same_close_decision, TIMESTAMPDIFF(MICROSECOND, o.generated_at, f.generated_at)/1000 AS delta_ms FROM crypto_ai.wallet_trade w JOIN crypto_ai.trade_signal o ON o.id=w.signal_id AND o.interval_code='1m' JOIN crypto_ai.trade_signal f ON f.symbol=o.symbol AND f.interval_code='5m' AND f.candle_open_time = o.candle_open_time - INTERVAL 4 MINUTE WHERE w.side='BUY' AND w.executed_at >= '2026-10-11 00:00:00' AND f.generated_at > o.generated_at ORDER BY w.id LIMIT 50;